package com.maurodelcore.expensetracker.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import lombok.Data;

import java.util.List;

/**
 * A registered user, stored in the {@code app_users} table. The password column
 * holds the BCrypt hash, never the plain-text password.
 */
@Data
@Entity
@Table(name = "app_users")
public class AppUser {

    /**
     * Primary key that uniquely identifies each user, generated by the database.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * The user's display name.
     */
    private String fullName;

    /**
     * The login name; unique so two users cannot share it.
     */
    @Column(unique = true)
    private String username;

    /**
     * The BCrypt hash of the user's password.
     */
    private String password;

    /**
     * The expenses owned by this user. The {@code user} field in {@link Expense} owns
     * the relationship ({@code mappedBy}). All operations on the user cascade to the
     * expenses, and with orphan removal, deleting the user also deletes their expenses.
     * Excluded from the JSON output.
     */
    @OneToMany(mappedBy = "user", cascade = CascadeType.ALL, orphanRemoval = true)
    @JsonIgnore
    private List<Expense> expenses;

    /**
     * The user's role, stored in the database as its name (for example "ADMIN" or "USER").
     */
    @Enumerated(EnumType.STRING)
    private Role role;
}